1	import { runScenario, type Scenario } from "./claim-office.js";
2	
3	const readStdin = async (): Promise<string> => {
4	  const chunks: Buffer[] = [];
5	
6	  for await (const chunk of process.stdin) {
7	    chunks.push(chunk as Buffer);
8	  }
9	
10	  return Buffer.concat(chunks).toString("utf8");
11	};
12	
13	// The CLI is a thin transport shell around runScenario: read a scenario from
14	// stdin, run it, write the result to stdout. All domain rules live in
15	// claim-office.ts, so this file should stay free of them.
16	// A rejected scenario reports the reason on stderr and exits non-zero, leaving
17	// stdout empty — a caller parsing stdout must never see partial results.
18	try {
19	  const scenario = JSON.parse(await readStdin()) as Scenario;
20	
21	  process.stdout.write(JSON.stringify(runScenario(scenario)));
22	} catch (error) {
23	  process.stderr.write(`${(error as Error).message}\n`);
24	  process.exit(1);
25	}
