1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface Incident {
23	  cause: string;
24	  damages: Damage[];
25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  policy: number;
30	  incident: Incident;
31	}
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export interface QuoteResult {
41	  premium: number;
42	}
43	
44	export interface ClaimResult {
45	  payout: number;
46	  remainingCap: number;
47	}
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export interface ScenarioResult {
52	  results: StepResult[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	
57	const FIRST_INSURANCE_SURCHARGE = 0.1;
58	
59	const CURSE_SURCHARGE = 0.5;
60	
61	const HIGH_ENCHANTMENT_LEVEL = 5;
62	
63	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
64	
65	const LOYALTY_YEARS = 2;
66	
67	const LOYALTY_DISCOUNT = 0.2;
68	
69	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
70	
71	const BASE_PREMIUMS: Record<string, number> = {
72	  sword: 100,
73	  amulet: 60,
74	  staff: 80,
75	  potion: 40,
76	  rune: 25,
77	  moonstone: 25,
78	};
79	
80	const INSURANCE_VALUES: Record<string, number> = {
81	  sword: 1000,
82	  amulet: 600,
83	  staff: 800,
84	  potion: 400,
85	  rune: 250,
86	  moonstone: 250,
87	};
88	
89	const DEDUCTIBLE = 100;
90	
91	const HALVED_PAYOUT_ENCHANTMENT = 8;
92	
93	const HALVED_PAYOUT_RATE = 0.5;
94	
95	const CAP_MULTIPLIER = 2;
96	
97	const BLOCK_SIZE = 3;
98	
99	const BLOCK_BASE_PREMIUM = 60;
100	
101	const countByType = <T>(values: T[], typeOf: (value: T) => string) =>
102	  values.reduce((counts, value) => {
103	    const type = typeOf(value);
104	
105	    return counts.set(type, (counts.get(type) ?? 0) + 1);
106	  }, new Map<string, number>());
107	
108	const itemCounts = (items: Item[]): Map<string, number> =>
109	  countByType(items, (item) => item.type);
110	
111	const typeBasePremium = (type: string, count: number): number =>
112	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
113	
114	const policyBasePremium = (items: Item[]): number =>
115	  [...itemCounts(items)].reduce(
116	    (total, [type, count]) => total + typeBasePremium(type, count),
117	    0,
118	  );
119	
120	// Modifiers below all express a rate applied to some base. Keep every one of
121	// them in the form `base + base * RATE`. The algebraically equivalent
122	// `base * (1 + RATE)` is NOT safe here: 100 * 1.1 === 110.00000000000001 in
123	// IEEE-754, and Math.ceil turns that into 116 instead of 115. Ceil amplifies
124	// upward float error rather than absorbing it.
125	
126	// Item-specific modifiers: each is computed on the affected item's OWN base
127	// premium, then summed across items. Note this is the item's UNIT base premium
128	// — never the block-adjusted one. A rune inside a block of 3 is still
129	// surcharged on its own 25 G, not on its 20 G share of the block.
130	const unitBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];
131	
132	const isHighlyEnchanted = (item: Item): boolean =>
133	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
134	
135	const itemSurchargeRate = (item: Item): number =>
136	  (item.cursed ? CURSE_SURCHARGE : 0) +
137	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE : 0);
138	
139	const itemSurcharges = (items: Item[]): number =>
140	  items.reduce(
141	    (total, item) => total + unitBasePremium(item) * itemSurchargeRate(item),
142	    0,
143	  );
144	
145	// Policy-wide modifiers: each is computed on the policy base premium (the sum
146	// of all item base premiums), independent of which items make it up.
147	const isLoyal = (customer: Customer): boolean =>
148	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
149	
150	const policyModifierRate = (
151	  customer: Customer,
152	  isFollowUpContract: boolean,
153	): number =>
154	  FIRST_INSURANCE_SURCHARGE -
155	  (isLoyal(customer) ? LOYALTY_DISCOUNT : 0) -
156	  (isFollowUpContract ? FOLLOW_UP_CONTRACT_DISCOUNT : 0);
157	
158	// The MHPCO catalogue. A type outside it is not an item the office can price
159	// or insure, so both quotes and claims reject it up front — before any
160	// counting rule gets a chance to describe it as merely under-insured.
161	const rejectUnknownTypes = (types: string[]): void => {
162	  for (const type of types) {
163	    if (!(type in BASE_PREMIUMS)) {
164	      throw new Error(`Unknown item type: ${type}`);
165	    }
166	  }
167	};
168	
169	const quote = (
170	  items: Item[],
171	  customer: Customer,
172	  isFollowUpContract: boolean,
173	): QuoteResult => {
174	  rejectUnknownTypes(items.map((item) => item.type));
175	
176	  const policyBase = policyBasePremium(items);
177	  const policyModifiers =
178	    policyBase * policyModifierRate(customer, isFollowUpContract);
179	
180	  return {
181	    premium: Math.ceil(
182	      policyBase + itemSurcharges(items) + policyModifiers + PROCESSING_FEE,
183	    ),
184	  };
185	};
186	
187	interface Policy {
188	  items: Item[];
189	  remainingCap: number;
190	}
191	
192	const insuranceSum = (items: Item[]): number =>
193	  items.reduce((total, item) => total + INSURANCE_VALUES[item.type], 0);
194	
195	const openPolicy = (items: Item[]): Policy => ({
196	  items,
197	  remainingCap: insuranceSum(items) * CAP_MULTIPLIER,
198	});
199	
200	// Note this enchantment threshold (8) is the CLAIM rule and is distinct from
201	// HIGH_ENCHANTMENT_LEVEL (5), which is the premium rule.
202	const reimbursementRate = (item: Item): number =>
203	  (item.enchantment ?? 0) >= HALVED_PAYOUT_ENCHANTMENT ? HALVED_PAYOUT_RATE : 1;
204	
205	// The rate comes from the insured item of the damaged type. Both validations
206	// in `claim` have already run by the time this is reached, so a matching item
207	// is guaranteed to exist: unknown types are rejected outright, and a type with
208	// more damages than insured items is rejected as over-claiming.
209	const insuredItemOfType = (policy: Policy, itemType: string): Item =>
210	  policy.items.find((item) => item.type === itemType)!;
211	
212	// Each damage entry carries its own deductible: an incident that harms three
213	// insured items subtracts the deductible three times, not once. The deductible
214	// can reduce a damage to zero but never below — a damage smaller than the
215	// deductible simply pays nothing, it does not refund the policy's cap.
216	const reimbursement = (damage: Damage, item: Item): number =>
217	  Math.max(damage.amount * reimbursementRate(item) - DEDUCTIBLE, 0);
218	
219	// What the incident would pay out if the policy had unlimited cap.
220	// Payouts round DOWN where premiums round UP — both in the MHPCO's favour.
221	// Round once, here, so the figure reported to the customer and the figure
222	// charged against the cap can never drift apart.
223	const desiredPayout = (policy: Policy, incident: Incident): number =>
224	  Math.floor(
225	    incident.damages.reduce(
226	      (total, damage) =>
227	        total +
228	        reimbursement(damage, insuredItemOfType(policy, damage.itemType)),
229	      0,
230	    ),
231	  );
232	
233	// A policy covers a fixed set of items, so an incident cannot damage more
234	// items of a type than the policy insures. Over-claiming rejects the whole
235	// claim rather than paying out the covered part.
236	const rejectOverClaiming = (policy: Policy, incident: Incident): void => {
237	  const insured = itemCounts(policy.items);
238	  const damaged = countByType(incident.damages, (damage) => damage.itemType);
239	
240	  for (const [type, count] of damaged) {
241	    if (count > (insured.get(type) ?? 0)) {
242	      throw new Error(
243	        `Claim covers more ${type} damages than the policy insures`,
244	      );
245	    }
246	  }
247	};
248	
249	const rejectNegativeDamages = (incident: Incident): void => {
250	  for (const damage of incident.damages) {
251	    if (damage.amount < 0) {
252	      throw new Error(`Damage amount cannot be negative: ${damage.amount}`);
253	    }
254	  }
255	};
256	
257	// The cap is the ceiling on everything the policy will ever pay: each claim
258	// takes what it can from the remainder, and once drained the policy pays 0.
259	const claim = (policy: Policy, incident: Incident): ClaimResult => {
260	  rejectNegativeDamages(incident);
261	  rejectUnknownTypes(incident.damages.map((damage) => damage.itemType));
262	  rejectOverClaiming(policy, incident);
263	
264	  const payout = Math.min(desiredPayout(policy, incident), policy.remainingCap);
265	
266	  policy.remainingCap -= payout;
267	
268	  return { payout, remainingCap: policy.remainingCap };
269	};
270	
271	export const runScenario = (scenario: Scenario): ScenarioResult => {
272	  const results: StepResult[] = [];
273	  const policies = new Map<number, Policy>();
274	
275	  // Every quote after the first in a scenario is a follow-up contract, so the
276	  // presence of an earlier policy is exactly the follow-up condition.
277	  scenario.steps.forEach((step, index) => {
278	    if (step.op === "quote") {
279	      const isFollowUpContract = policies.size > 0;
280	
281	      results.push(quote(step.items, scenario.customer, isFollowUpContract));
282	      policies.set(index, openPolicy(step.items));
283	
284	      return;
285	    }
286	
287	    results.push(claim(policies.get(step.policy)!, step.incident));
288	  });
289	
290	  return { results };
291	};
